// Re-implementing joins on unstructured document queries manually
struct Post {
    id: u64,
    author_id: u64,
    title: String,
}

struct Author {
    id: u64,
    name: String,
}

fn get_posts_with_authors(posts: &[Post], authors: &[Author]) -> Vec<(Post, Author)> {
    let mut results = Vec::new();
    for post in posts {
        // O(n * m) nested loop simulation of relational join
        if let Some(author) = authors.iter().find(|a| a.id == post.author_id) {
            results.push((post.clone(), author.clone()));
        }
    }
    results
}
