fix:
Perform joins directly inside the database system.

```
// Query that leverages database-side indexes and joins
let posts_with_authors = sqlx::query!(
    "SELECT p.*, a.name FROM posts p JOIN authors a ON p.author_id = a.id"
)
.fetch_all(&mut pool)
.await?;
```
